type TLineDesc = [level: number, text: string]

export const splitLine = (line: string): TLineDesc => {

	const [_, prefix, str] = line.match(/^(\s*)(.*)$/) || ['', '', '']
	const trimmed = str.trim()
	if (trimmed === '') {
		return [0, '']
	}
	else {
		return [indentLevel(prefix), trimmed]
	}
}

